\set ON_ERROR_STOP on
create or replace function pg_temp.assert_true(c boolean,m text)returns void language plpgsql as $$begin if not coalesce(c,false)then raise exception 'ASSERTION FAILED: %',m;end if;end$$;
insert into auth.users(id,email,raw_user_meta_data)values('28000000-0000-4000-8000-000000000001','ai-admin@example.test','{"display_name":"AI Administrator"}'),('28000000-0000-4000-8000-000000000002','ai-tech@example.test','{"display_name":"AI Technician"}');set fmworks.profile_admin_rpc='on';update public.profiles set role=case when id='28000000-0000-4000-8000-000000000001'then'administrator'else'technician'end,is_active=true,deleted_at=null,password_change_required=false where id in('28000000-0000-4000-8000-000000000001','28000000-0000-4000-8000-000000000002');reset fmworks.profile_admin_rpc;
select pg_temp.assert_true((select count(*)=3 from public.ai_prompt_versions where status='APPROVED'),'approved versioned prompt baseline exists');select pg_temp.assert_true((select external_processing_approved=false from public.ai_provider_configurations where provider_type='MOCK'),'external processing is independently unapproved');
set role authenticated;select set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000001',false);select public.test_ai_configuration()as health\gset
select pg_temp.assert_true((:'health'::jsonb)->>'status'='READY'and(:'health'::jsonb)->>'credential_exposed'='false','safe MOCK connectivity test succeeds');select pg_temp.assert_true(exists(select 1 from public.ai_operation_audit where operation_type='HEALTH_CHECK'and safe_diagnostic not ilike'%key%'),'safe audit is persisted without credentials');reset role;
set role authenticated;select set_config('request.jwt.claim.sub','28000000-0000-4000-8000-000000000002',false);select pg_temp.assert_true((select count(*)=0 from public.ai_provider_configurations)and(select count(*)=0 from public.ai_operation_audit),'Technician cannot read AI administration');select pg_temp.assert_true(((public.test_ai_configuration())::jsonb)->>'code'='ACCESS_DENIED','Technician cannot test AI configuration');reset role;
select pg_temp.assert_true((select relrowsecurity from pg_class where oid='public.ai_operation_audit'::regclass),'AI audit RLS enabled');
